import{_ as n,a0 as s,w as p,s as u,ao as o,I as r,x as l,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"开源社区透明度的五个层次 | LCTT x X-CMD","titleTemplate":false,"description":"开源社区透明度的五个层次 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"开源社区透明度的五个层次 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"开源社区透明度的五个层次 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220212 5 levels of transparency for open source communities","title":"开源社区透明度的五个层次","tag":"202205","desc":""},"relativePath":"202205/20220212 5 levels of transparency for open source communities.md","filePath":"[post].md"}'),d={name:"202205/20220212 5 levels of transparency for open source communities.md"};function m(f,e,h,T,b,x){const t=s("Link");return p(),u("div",null,[e[20]||(e[20]=o('<h1 id="开源社区透明度的五个层次" tabindex="-1">开源社区透明度的五个层次 <a class="header-anchor" href="#开源社区透明度的五个层次" aria-label="Permalink to “开源社区透明度的五个层次”">​</a></h1><blockquote><p>如果想让开源社区繁荣发展，管理者需要达到透明度的五个层次。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202205/15/150842yrvm9v5qbbd7a355.jpg" alt=""></p><p>开源社区的管理者必须意识到社区有五个层次的透明度，这对于建设繁荣发展的开源社区来说至关重要。</p><p>本文将详细介绍各个层次及其目标与作用。不过首先，我想谈一谈透明度对开源社区的重要性。</p><h3 id="为什么开源社区需要保证透明度" tabindex="-1">为什么开源社区需要保证透明度？ <a class="header-anchor" href="#为什么开源社区需要保证透明度" aria-label="Permalink to “为什么开源社区需要保证透明度？”">​</a></h3><ul><li>透明能够增进社区成员之间的信任，促进合作。</li><li>开放是社区合作和交流的前提。</li><li>只有在开放透明的环境下，开源工作才能避免矛盾与冲突。</li><li>社区管理者需要向参与者报告社区情况。</li><li>向成员公开社区各项情况，营造信任氛围，有利于社区健康发展。</li></ul><h3 id="透明度的五个层次" tabindex="-1">透明度的五个层次 <a class="header-anchor" href="#透明度的五个层次" aria-label="Permalink to “透明度的五个层次”">​</a></h3><h4 id="层次一-发布源码" tabindex="-1">层次一：发布源码 <a class="header-anchor" href="#层次一-发布源码" aria-label="Permalink to “层次一：发布源码”">​</a></h4>',9)),r("p",null,[e[2]||(e[2]=l("在这一层次，社区需要遵循 ",-1)),a(t,{href:"https://opensource.org/licenses"},{default:i(()=>[...e[0]||(e[0]=[l("OSI 认可的许可证",-1)])]),_:1}),e[3]||(e[3]=l("，在 ",-1)),a(t,{href:"https://opensource.com/tags/git"},{default:i(()=>[...e[1]||(e[1]=[l("Git",-1)])]),_:1}),e[4]||(e[4]=l(" 等公开的版本控制系统上发布源码。",-1))]),e[21]||(e[21]=o('<p>层次一的目标在于创建开源项目。</p><ul><li>建立开源社区，理应达到这一层次。因为没有公开源代码，也就无所谓开源项目。</li><li>开源项目的核心便是参与者们编写的源码，并在 OSI 批准的许可证下授权。</li><li>公开的版本控制系统能够促进合作，使得每一位开发者都能了解项目情况，理解合作模式。</li></ul><h4 id="层次二-发布社区指南" tabindex="-1">层次二：发布社区指南 <a class="header-anchor" href="#层次二-发布社区指南" aria-label="Permalink to “层次二：发布社区指南”">​</a></h4><p>达到这一层次，需要发布相关文档以及资源。也可通过组织活动来指导社区成员。</p><p>层次二的目标在于为一个开源项目建立和发展一个开源社区。</p><ul><li>建立一个活跃的社区需要的不仅仅是源代码。</li><li>公开项目开展方式和贡献方式，能够吸引更多的开发者参与到项目当中。</li><li>为了推动社区的发展，管理者可能需要举办一些重要活动，并为贡献者们筹办一些特殊的活动。</li></ul><h4 id="层次三-继往开来" tabindex="-1">层次三：继往开来 <a class="header-anchor" href="#层次三-继往开来" aria-label="Permalink to “层次三：继往开来”">​</a></h4><p>到了这个层次，管理者有必要分享自己对于社区的见解，发布项目进展情况报告。</p><p>层次三的目标在于继往开来，确保社区进入后续阶段后能够更上一层楼，实现长远发展。</p><ul><li>随着开源社区的发展，社区内的情况将会越来越难以把握。</li><li>公开社区活动，让成员意识到自己的付出能够为公众所见，为公众所识。</li><li>在这一层次，无论是报告还是分析，发布的时间并不固定，使用的工具也无定法。</li></ul><h4 id="层次四-掌握社区的动态" tabindex="-1">层次四：掌握社区的动态 <a class="header-anchor" href="#层次四-掌握社区的动态" aria-label="Permalink to “层次四：掌握社区的动态”">​</a></h4><p>这一层次就在于倾听社区声音：通过观察社区活动，关注项目发展；跟进软件开发进度，据此采取合适的应对措施。</p><p>层次四的目标在于保持科学严谨的态度，持续把握社区的发展情况及发展轨迹，引导社区朝着下一个层次迈进。</p><ul><li>建立报告机制，运用分析工具，掌握社区动态。</li><li>将社区的各项活动与社区成员的反响与基线和社区内的其他活动进行比较。</li><li>坚持倾听社区声音，形成对于社区更深刻的见解。</li></ul><h4 id="层次五-维护社区-长久发展" tabindex="-1">层次五：维护社区，长久发展 <a class="header-anchor" href="#层次五-维护社区-长久发展" aria-label="Permalink to “层次五：维护社区，长久发展”">​</a></h4><p>最后一个层次就是依据社区各项指标，提高社区成员的参与度。</p><p>层次五的目标在于制定行之有效、能够产生积极影响的决策方案，让开发者更好地参与社区项目。</p><ul><li>适当调整系统，以适应社区各项指标的变动。</li><li>跟进这些变动，理解它们是如何通过各项指标和数据分析体现出来的。</li><li>针对社区维护者与开发者，制定服务等级协议和问责制度，为其设立参与度目标，确保项目整体顺利进行。</li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>开源社区管理者需要做到上述五个层次，保证透明度，才能构建起一个繁荣发展的社区。</p><hr>',21)),r("p",null,[e[6]||(e[6]=l("via: ",-1)),a(t,{href:"https://opensource.com/article/22/2/transparency-open-source-communities"},{default:i(()=>[...e[5]||(e[5]=[l("https://opensource.com/article/22/2/transparency-open-source-communities",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=l("作者：",-1)),a(t,{href:"https://opensource.com/users/egaleano"},{default:i(()=>[...e[7]||(e[7]=[l("Emilio Galeano Gryciuk",-1)])]),_:1}),e[12]||(e[12]=l(" 选题：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[8]||(e[8]=[l("lujun9972",-1)])]),_:1}),e[13]||(e[13]=l(" 译者：",-1)),a(t,{href:"https://github.com/aREversez"},{default:i(()=>[...e[9]||(e[9]=[l("aREversez",-1)])]),_:1}),e[14]||(e[14]=l(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[10]||(e[10]=[l("wxy",-1)])]),_:1})]),r("p",null,[e[17]||(e[17]=l("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[15]||(e[15]=[l("LCTT",-1)])]),_:1}),e[18]||(e[18]=l(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...e[16]||(e[16]=[l("Linux中国",-1)])]),_:1}),e[19]||(e[19]=l(" 荣誉推出",-1))])])}const P=n(d,[["render",m]]);export{k as __pageData,P as default};
